```yaml
name: Assign label to bot PRs

on:
  pull_request_target:
    types: [opened, reopened]

permissions:
  pull-requests: write

jobs:
  assign-label:
    runs-on: ubuntu-latest
    if: |
      github.event.pull_request.user.login == 'dependabot[bot]' ||
      github.event.pull_request.user.login == 'transifex-integration[bot]' ||
      github.event.pull_request.user.login == 'imgbot[bot]'
    steps:
      - name: Assign label
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const label = ':heavy_check_mark: dependencies';

            // Check if label already exists on the PR
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            const hasLabel = pr.labels.some(l => l.name === label);
            if (hasLabel) {
              console.log(`Label '${label}' is already assigned.`);
              return;
            }

            // Add the label
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: [label]
            });

            console.log(`Assigned label '${label}' to PR #${context.issue.number}`);
```

